package workspace

import crew.User
import plm.PlmFreeCadPart
import grails.plugin.springsecurity.annotation.Secured

@Secured(['ROLE_PLM_USER', 'ROLE_ADMIN'])
class WorkspaceController {
    def springSecurityService
    PlmWorkspaceService plmWorkspaceService
    PlmWorkspaceSyncService plmWorkspaceSyncService
    PlmWorkspaceSecurityService plmWorkspaceSecurityService
    def plmFreeCadSecurityService

    private User user() { springSecurityService.currentUser as User }

    // Avoid the malformed /%7D/ prefix generated by action-based redirects.
    private void goToWorkspace(Long workspaceId) {
        String base = request.contextPath ?: ''
        response.sendRedirect("${base}/workspace/show/${workspaceId}".toString())
    }

    private void goToWorkspaceList() {
        String base = request.contextPath ?: ''
        response.sendRedirect("${base}/workspace/index".toString())
    }
    def index() { [workspaces: plmWorkspaceService.accessible(user()), currentUserId: user()?.id] }
    def show(Long id) {
        PlmWorkspace w = PlmWorkspace.get(id)
        if (!plmWorkspaceSecurityService.canView(w, user())) { response.sendError(403); return }
        boolean canEdit = plmWorkspaceSecurityService.canEdit(w, user())
        String partQuery = (params.partQuery ?: '').toString().trim().take(120)
        List<PlmFreeCadPart> searchResults = []
        if (canEdit && partQuery.length() >= 2) {
            // Search current PLM parts by name or label, as in the PLM parts search.
            String escaped = partQuery
            searchResults = PlmFreeCadPart.createCriteria().list(max: 100) {
                eq('active', true)
                isNull('nextVersion')
                or {
                    ilike('originalName', "%${escaped}%")
                    ilike('label', "%${escaped}%")
                }
                order('originalName', 'asc')
            }.findAll { PlmFreeCadPart p ->
                plmFreeCadSecurityService.canDownloadFile(p, user())
            }.take(30)
        }
        [workspace: w, inventory: plmWorkspaceSyncService.inventory(w, user()),
         canEdit: canEdit, partQuery: partQuery, searchResults: searchResults,
         isOwner: plmWorkspaceSecurityService.isOwner(w, user()),
         members: PlmWorkspaceMember.findAllByWorkspace(w)]
    }
    @Secured(['ROLE_PLM_USER', 'ROLE_ADMIN'])
    def debugAccess() {
        User current = springSecurityService.currentUser as User

        render([
            username: current?.username,
            authorities: springSecurityService.authentication?.authorities
                ?.collect { it.authority }
        ] as grails.converters.JSON)
}
    def create() {
        if (request.method != 'POST') { response.sendError(405); return }
        try { def w = plmWorkspaceService.create(user(), params.name, params.description); goToWorkspace(w.id as Long) }
        catch (Exception e) { flash.error = e.message; goToWorkspaceList() }
    }
    def updateWorkspace(Long id) {
        if (request.method != 'POST') { response.sendError(405); return }
        try {
            plmWorkspaceService.updateWorkspace(user(), id, params.name, params.description)
        } catch (Exception e) {
            flash.error = e.message
        }
        goToWorkspaceList()
    }
    def duplicate(Long id) {
        if (request.method != 'POST') { response.sendError(405); return }
        try { def w = plmWorkspaceService.duplicate(user(), id, params.name); goToWorkspace(w.id as Long) }
        catch (Exception e) { flash.error = e.message; goToWorkspaceList() }
    }
    def addPart(Long id, Long partId) {
        if (request.method != 'POST') { response.sendError(405); return }
        try {
            plmWorkspaceService.addPart(user(), id, partId, params.long('inventoryRevision'))
        } catch (Exception e) {
            flash.error = e.message
        }
        // Use a root-relative URL to avoid a malformed redirect prefix.
        goToWorkspace(id)
    }
    def removePart(Long id, Long partId) {
        if (request.method != 'POST') { response.sendError(405); return }
        try { plmWorkspaceService.removePart(user(), id, partId, params.long('inventoryRevision')); goToWorkspace(id) }
        catch (Exception e) { flash.error = e.message; goToWorkspace(id) }
    }
    def approveVersion(Long id, Long partId) {
        if (request.method != 'POST') { response.sendError(405); return }
        try { plmWorkspaceService.approveLatest(user(), id, partId, params.long('inventoryRevision')); goToWorkspace(id) }
        catch (Exception e) { flash.error = e.message; goToWorkspace(id) }
    }
    def setMember(Long id) {
        if (request.method != 'POST') { response.sendError(405); return }
        try {
            User member = User.findByUsername(params.username)
            plmWorkspaceService.setMember(user(), id, member, params.role)
        } catch (Exception e) { flash.error = e.message }
        goToWorkspace(id)
    }
    def removeMember(Long id, Long userId) {
        if (request.method != 'POST') { response.sendError(405); return }
        try { plmWorkspaceService.removeMember(user(), id, User.get(userId)) }
        catch (Exception e) { flash.error = e.message }
        goToWorkspace(id)
    }
    def delete(Long id) {
        if (request.method != 'POST') { response.sendError(405); return }
        try { plmWorkspaceService.deleteWorkspace(user(), id); goToWorkspaceList() }
        catch (Exception e) { flash.error = e.message; goToWorkspace(id) }
    }
    // GET /workspace/selectPart?partId=... : standalone entry point from PLM screens.
    def selectPart(Long partId) {
        PlmFreeCadPart part = PlmFreeCadPart.get(partId)
        if (!part) { response.sendError(404); return }
        [part: part, workspaces: plmWorkspaceService.accessible(user()).findAll {
            plmWorkspaceSecurityService.canEdit(it, user())
        }]
    }
}